mapper.select:
SELECT 
FROM commission_record
WHERE distributor_id = #{distributorId}
ORDER BY create_time DESC
LIMIT #{limit} OFFSET #{offset}

mapper.insert:
INSERT INTO commission_record (
    distributor_id, order_no, user_id, type, amount, order_amount, rate,
    status, settle_time
) VALUES (
    #{distributorId}, #{orderNo}, #{userId}, #{type}, #{amount}, #{orderAmount}, #{rate},
    #{status}, #{settleTime}
)

mapper.select:
SELECT COALESCE(SUM(amount), 0) FROM commission_record
WHERE distributor_id = #{distributorId}
  AND DATE(create_time) = CURDATE()

SELECT COUNT(DISTINCT order_no) FROM commission_record
WHERE distributor_id = #{distributorId}
  AND DATE(create_time) = CURDATE()

SELECT COUNT(*) FROM commission_record
WHERE distributor_id = #{distributorId}
  AND status = 0

SELECT COALESCE(SUM(amount), 0) FROM commission_record
WHERE distributor_id = #{distributorId}
  AND status = 0
